        FOR i IN 0 .. FLOOR((DBMS_LOB.GETLENGTH(v_resultado) - 1) / 30000) LOOP
            HTP.PRN(DBMS_LOB.SUBSTR(v_resultado, 30000, i * 30000 + 1));
        END LOOP;

        HTP.PRN(''}'');
    END IF;

EXCEPTION
