'DECLARE
    v_resultado CLOB;
    v_resultado_texto VARCHAR2(32767);
BEGIN
    IF NVL(:p_token, '' '') = '' '' THEN
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
            "success": false,
            "mensaje": "Debe indicar el TOKEN",
            "data": {}
        }'');
        RETURN;
    END IF;

    -- Llamada a la función con los parámetros de búsqueda
    v_resultado := FN_BUSCAR_ASEGURADOS(
        p_tipo_doc_identificacion => :p_tipo_doc_identificacion,
        p_num_doc_identificacion => :p_num_doc_identificacion,
        p_nombre => :p_nombre,
        p_apellido_paterno => :p_apellido_paterno,
        p_apellido_materno => :p_apellido_materno,
        p_fec_nacimiento => TO_DATE(:p_fec_nacimiento, ''YYYY-MM-DD''),
        p_CodCia      => :P_CODCIA,
        p_CodEmpresa  => :P_CODEMPRESA
    );

  -- Convertir el CLOB a VARCHAR2 para comparación
    BEGIN
        v_resultado_texto := ' || 'DBMS_LOB.SUBSTR(v_resultado, 32767, 1); 
    EXCEPTION
        WHEN OTHERS THEN
            v_resultado_texto := ''''; -- Si no se puede convertir, dejamos vacío
    END;

    -- Configurar el encabezado para JSON
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;

    -- Verificar si v_resultado está vacío o es nulo
    IF v_resultado_texto IS NULL OR LENGTH(TRIM(v_resultado_texto)) < 10 THEN
        HTP.PRN(''{
            "success": false,
            "mensaje": "No se encontraron asegurados con los parametros indicados",
            "data": []
        }'');
    ELSE
        -- Mostrar el resultado si hay datos
        HTP.PRN(''{
            "success": true,
            "mensaje": "",
            "data": '' || NVL(v_resultado, ''{}'') || ''
        }'');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        -- Configurar el encabezado para JSON en caso de error
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
     ' || '   OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{ "error": "'' || SQLERRM || ''" }'');
END;');

