  ORDS.DEFINE_HANDLER(
      p_module_name    => 'thona-api',
      p_pattern        => 'obtiene_causasiniestro',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => NULL,
      p_source         => 
'DECLARE
    v_resultado CLOB;
    l_offset    INTEGER := 1;
    l_chunk     VARCHAR2(32767);
BEGIN
    -- Validar token
    IF NVL(:p_token, '' '') = '' '' THEN
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
            "success": false,
            "mensaje": "Debe indicar el TOKEN",
            "data": {}
        }'');
        RETURN;
    END IF;

    -- Llamar a la función para obtener las causas de siniestro
    v_resultado := FN_OBTENER_CAUSAS_SINIESTRO(
        p_codvalor => :p_codvalor,
        p_descval  => :p_descval
    );

    -- Establecer cabecera HTTP
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
    OWA_UTIL.HTTP_HEADER_CLOSE;

    -- Evaluar contenido del CLOB
    IF v_resultado IS NULL OR DBMS_LOB.GETLENGTH(v_resultado) < 3 THEN
        HTP.PRN(''{
            "success": false,
            "mensaje": "No se encontraron causas de siniestro con los parámetros indicados o hubo' || ' un problema.",
            "data": []
        }'');
    ELSIF DBMS_LOB.INSTR(v_resultado, ''{ "error"'') > 0 THEN
        -- Extraer mensaje de error dentro del JSON
        HTP.PRN(''{
            "success": false,
            "mensaje": "Error de la base de datos",
            "data": []
        }'');
    ELSE
        -- Construir JSON correctamente fragmentado
        HTP.PRN(''{ "success": true, "mensaje": "", "data": '');
        WHILE l_offset <= DBMS_LOB.GETLENGTH(v_resultado) LOOP
            l_chunk := DBMS_LOB.SUBSTR(v_resultado, 32767, l_offset);
            HTP.PRN(l_chunk);
            l_offset := l_offset + LENGTH(l_chunk);
        END LOOP;
        HTP.PRN('' }'');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        -- Manejo de errores general
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
