    v_resultado_texto VARCHAR2(32767);
    v_output    VARCHAR2(32767);
BEGIN
   IF NVL(:p_token, '' '') = '' '' THEN
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
            "success": false,
            "mensaje": "Debe indicar el TOKEN",
            "data": {}
        }'');
        RETURN;
    END IF;


    v_resultado := FN_OBTIENE_REQUISITOS_COB(
        P_IDPOLIZA     => :p_idpoliza,
        P_CODASEGURADO => :p_codasegurado,
        P_CODSUBGRUPO  => :p_codsubgrupo,
        P_CODCIA       => :p_codcia,
        P_CODEMPRESA   => :p_codempresa
    );


    -- Convertir el CLOB a VARCHAR2 para comparación
    BEGIN
        v_resultado_texto := DBMS_LOB.SUBSTR(v_resultado, 32767, 1); 
    EXCEPTION
        WHEN OTHERS THEN
            v_resultado_texto := ''''; -- Si no se puede convertir, dejamos vacío
    END;

    v_output' || ' := DBMS_LOB.SUBSTR(v_resultado, 32767, 1);


    -- Configurar el encabezado para JSON
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
    OWA_UTIL.HTTP_HEADER_CLOSE;

    IF v_resultado_texto IS NULL OR LENGTH(TRIM(v_resultado_texto)) < 10 THEN
        HTP.PRN(''{
            "success": false,
            "mensaje": "No se encontro requisitos con los parametros indicados",
            "data": []
        }'');
    ELSE
        -- Mostrar el resultado si hay datos
        HTP.PRN(''{
            "success": true,
            "mensaje": "",
            "data": '' || NVL(v_output, ''{}'') || ''
        }'');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        	-- Configurar el encabezado para JSON
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
        OWA_UTIL.HTTP_HEADER_CLOSE;
         HTP.PRN(''{
            "success": false,
            "mensaje": "'' || SQLERRM || ''",
            "data": []
        }'');

END;');

